      return result;
    } finally {
      if (timer) clearInterval(timer); reviewStops.delete(stop);
      try { if (!ports.onReviewProgress && ctx.hasUI) ctx.ui.setStatus("scholar-review", undefined); } catch { /* best-effort status cleanup */ }
