    const packets = "objectives" in target
      ? planLessonUnitPackets(unit, target, sourceHash, ctx.model?.contextWindow)
      : [planTutorExplanationPacket({ id: unit.entryId, title: unit.title, markdown: unit.markdown, sourcePages: unit.sourcePages, keyPoints: unit.keyPoints })];
