      try {
        const receipts = await runReviewPass({
          book: draft, section: "objectives" in target ? target : undefined, config: { ...ports.getConfig() }, ctx, signal,
          sourceHash, contentHash: unit.revision,
          snapshots: "objectives" in target ? currentReviewSnapshots(target, sourceHash) : target.snapshots || [],
          prepared: true, existingReviews: recordReviews(target), onCheckpoint: checkpoints.save,
