  if (unitAudited(receipts, unit, sourceHash)) return;   // needs unit.roles
  if (running && !sameWork) running.stop.abort(new Error("A newer revision of this unit replaced the audited one."));
  startUnitAudit(state, draft, reviewStore?..., unit, sourceHash, ctx, planExamReviewPackets(exam, questions, draft));
};
```

