 * Packets, receipt storage and the audited scope belong to the caller. */
const startUnitAudit = (state: PreparationAuditor, draft: ScholarBook, store: ReviewReceiptStore,
  unit: AuditUnit, sourceHash: string, ctx: ExtensionContext, packets: ReviewPacket[],
  scope: { section?: ScholarSection; snapshots?: ScholarSnapshot[] } = {}): void => {
  const stop = new AbortController();
  const signal = ctx.signal ? AbortSignal.any([stop.signal, ctx.signal]) : stop.signal;
  reviewStops.add(stop);
  const checkpoints = saveReviewCheckpoints(draft, store, unit.revision, state.activation, ctx);
  const task: UnitAudit = { unit, sourceHash, roles: [...unit.roles], stop, settled: false, done: Promise.resolve() };
  state.units.set(unit.key, task);
  task.done = (async () => {
    try {
      const receipts = await runReviewPass({
        book: draft, section: scope.section, config: { ...ports.getConfig() }, ctx, signal,
        sourceHash, contentHash: unit.revision,
        snapshots: scope.snapshots || [],

